              { slide: 4, type: 'image', title: 'The OSSLT at a glance (infographic)', why: 'One-page picture of what the test measures — the same four skills the portfolio tracks.', source: 'EQAO — OSSLT at a glance', url: 'https://www.eqao.com/wp-content/uploads/2023/11/infographic-at-a-glance-osslt.pdf', search: 'EQAO infographic at a glance OSSLT', src: '' }
