      'purpose':             { k2: 'Your reason for reading, like finding a time.', g35: 'The reason you are reading; the question you want answered.', g68: 'The reason you are reading a text: the question you want the text to answer.' },
      'scan':                { k2: 'Look fast for one thing, like your name.', g35: 'Moving your eyes quickly to find one thing, like a name or number.', g68: 'Moving your eyes quickly over a text to find one specific detail such as a name, date or number.' },
      'skim':                { k2: 'Read fast to get the big idea.', g35: 'Reading quickly, using headings and first sentences, to get the main idea.', g68: 'Reading quickly through headings, bold words and first sentences to get the main idea.' },
