      'inference':           { k2: 'A smart guess from clues.', g35: 'A conclusion you make by putting together clues and what you know.', g68: 'A conclusion you reach by combining clues in the text with what you already know.' },
      'connection':          { k2: 'A link to your own life.', g35: 'A link between the text and your life, another text or the world.', g68: 'A link between the text and your own life, another text or the world, tied back to the text.' },
