      'sequence':            { k2: 'The order things happen: first, next, last.', g35: 'The order in which things happen, shown by words like first and then.', g68: 'The order in which events happen, marked by cue words such as first, then and by the end.' },
      'graphic text':        { k2: 'A chart, table, graph or map.', g35: 'A text that shows information with pictures: table, graph, map, schedule.', g68: 'A text that shows information visually, such as a table, schedule, graph, map or diagram.' },
